const mongoose = require('mongoose');

// ==========================================
// THE LINK RULES (The Schema Blueprint)
// ==========================================
// We define a template ruleset for our data. Every link saved MUST follow this structure.
const urlSchema = new mongoose.Schema({
  // 1. The original long link the user pasted
  longUrl: {
    type: String,
    required: true // The database will reject this form if the long URL is missing
  },
  
  // 2. The short code generated by our system (e.g., 'aZ91x')
  shortCode: {
    type: String,
    required: true,
    unique: true, // Crucial! No two links can ever share the same short code
    index: true   // Puts a "sticky note bookmark" on this column so lookups are lightning fast
  },
  
  // 3. When this link was made
  createdAt: {
    type: Date,
    default: Date.now // If we don't specify a date, it automatically sets it to right now
  }
});

// ==========================================
// EXPORT THE MODEL (Making the Filing Cabinet)
// ==========================================
// This turns our schema rules into a usable object called 'Url' and exports it.
// In your routes, you will type `Url.create()` or `Url.findOne()` to interact with the database.
module.exports = mongoose.model('Url', urlSchema);
